--[=[
	@class WuKongFacade
	@server

	本类为悟空框架的服务端用户门面. 

	:::caution

	1. 本类并非单例, 每个在线用户, 都将创建一个门面.
	2. 本类接口类似于客户端的 `WuKong`, 但是注意, 本类函数调用为面向对象, 需要使用冒号 `:`.

	:::
]=]
local WuKongFacade = {}

local Observer = require(game.ReplicatedStorage.WuKong.Observer)

local Container = require(game.ReplicatedStorage.WuKong.Types.Container)
local Slot = require(game.ReplicatedStorage.WuKong.Types.Slot)

WuKongFacade.__index = WuKongFacade

function WuKongFacade.new()
	local self = {}

	return setmetatable(self, WuKongFacade)
end

--[=[
	根据路径获取指定节点的容器,如果不存在, 则报错
	@return Container
]=]
function WuKongFacade:GetChild(location: string): Container.Type end

--[=[
	尝试获取指定节点的容器,
	@return hasContainer,Container
]=]
function WuKongFacade:TryGetChild(location: string): (boolean, Container.Type) end

--[=[
	获取该门面对应的用户容器
	@return Container
]=]
function WuKongFacade:GetContainer(): Container.Type end

--[=[
	获取该门面对应的用户容器,同 GetContainer()
	@return Container
]=]
function WuKongFacade:GetRootContainer(): Container.Type end

--[=[
	执行查询
	@param location string -- 查询地址
	@param ... any -- 查询参数
	@return any -- 查询结果
]=]
function WuKongFacade:ExecuteQuery(location: string, ...: any): any end

--[=[
	执行行动
	@param location string -- 行动地址
	@param ... any -- 行动参数
	@return any -- 行动结果
]=]
function WuKongFacade:ExecuteAction(location: string, ...: any): any end

--[=[
	执行验证
	@param location string -- 验证地址
	@param ... any -- 验证参数
	@return any -- 验证结果
]=]
function WuKongFacade:ExecuteValidate(location: string, ...: any): any end

--[=[
	获取Unix时间戳
	该时间戳受 WuKongTimer控制, 可以进行时间旅行.
	:::caution

	无论任何玩家的 Facade 实例, 调用此函数返回结果是相同的.
	:::

]=]
function WuKongFacade:GetUnixTime(location: string, ...: any): any end

--[=[
	获取命令列表
]=]
function WuKongFacade.GetCommandIds(): { string } end

--[=[
	注册容器属性观察者.
	注册成功后, 监听容器的属性值一旦改变, 将触发事件回调.
	@param path string? -- 路径,以起始容器为根,通过路径查找指定容器.
	@param func (container, propertyName)->() -- 事件回调
	@param container Container? -- 起始容器,为空则使用root容器
	@return Observer -- 观察者实例
]=]
function WuKongFacade:RegisterContainerPropertyObserver(
	path: string?,
	func: (
		container: Container.Type,
		propertyName: string
	) -> (),
	container: Container.Type?
): Observer.Type
end

--[=[
	注册容器插件数据观察者.
	注册成功后, 监听容器的插件数据一旦改变, 将触发事件回调.
	@param path string? -- 路径,以起始容器为根,通过路径查找指定容器.
	@param func (container, propertyName,value)->() -- 事件回调,比上一个增加了value回调, 即插件数据变更后的值
	@param container Container? -- 起始容器,为空则使用root容器
	@return Observer -- 观察者实例
]=]
function WuKongFacade:RegisterContainerPluginDataObserver(
	path: string?,
	func: (
		container: Container.Type,
		propertyName: string,
		value: any
	) -> (),
	container: Container.Type?
): Observer.Type
end

--[=[
	注册容器查询值变更事件
	注册成功后, 该查询的返回值一旦变更，将发起回调
	@param path string? -- 路径,以起始容器为根,通过路径查找指定容器.
	@param func (container, queryName,result)->() -- 事件回调, 参数为 目标容器, 事件名称 , 事件参数
	@param container Container? -- 起始容器,为空则使用root容器
	@return Observer -- 观察者实例
]=]
function WuKongFacade:RegisterContainerQueryObserver(
	path: string?,
	func: (
		container: Container.Type,
		queryName: string,
		result: {}
	) -> (),
	container: Container.Type?
)
end

--[=[
	注册容器插件行动观察者.
	注册成功后, 监听容器的某个行动一旦被执行, 将触发事件回调.
	@param path string? -- 路径,以起始容器为根,通过路径查找指定容器.
	@param func (container, actionName,args)->() -- 事件回调, 参数为 目标容器, 事件名称 , 事件参数
	@param container Container? -- 起始容器,为空则使用root容器
	@return Observer -- 观察者实例
]=]
function WuKongFacade:RegisterContainerActionObserver(
	path: string?,
	func: (
		container: Container.Type,
		actionName: string,
		args: {}
	) -> (),
	container: Container.Type?
): Observer.Type
end

--[=[
	注册格子观察者.

	注册成功后, 监听格子的元素数量一旦改变, 将触发事件回调.
	@param slotPath string -- 格子地址
	@param func (slot, propertyName)->() -- 事件回调
	@return Observer -- 观察者实例
]=]
function WuKongFacade:RegisterSlotObserver(
	slotPath: string,
	func: (slot: Slot.Type, propertyName: string) -> ()
): Observer.Type
end

--[=[
	注册行动观察者.

	注册成功后, 任何行动完成后, 都将触发事件回调.
	@param func  -- 事件回调, 其最多接受5个行动参数
	@return Observer -- 观察者实例
]=]
function WuKongFacade:RegisterActionObserver(func: (
	actionName: string,
	arg1: any?,
	arg2: any?,
	arg3: any?,
	arg4: any?,
	arg5: any?
) -> ()) end

--- 判断对象是否为 Slot
function WuKongFacade:IsSlot(t: {}): boolean end

--  修改格子内部元素的数量 (危险函数, 仅在数据迁移时使用)
function WuKongFacade:UpdateSlotCount(t: {}, count: number) end

--- 判断对象是否为 Container
function WuKongFacade:IsContainer(t: {}): boolean end

--- 判断对象是否为 ElementContainer
function WuKongFacade:IsElementContainer(t: {}): boolean end

--- 判断对象是否为 AggregateContainer
function WuKongFacade:IsAggregateContainer(t: {}): boolean end

--- 判断对象是否为 Element
function WuKongFacade:IsElement(t: {}): boolean end

--- 判断对象是否为 PropertyItem (特殊的Element, 包含了一个属性容器)
function WuKongFacade:IsPropertyItem(t: {}): boolean end

--- 获取该实例对应的UserId
function WuKongFacade:GetUserId() end

--- 获取元素配置, 如果无, 则返回空
function WuKongFacade:GetElementConfig(id: string): any end

--- 获取元素名称(多语言)
function WuKongFacade:GetElementName(id: string): string end

--- 获取元素扩展配置, 如果无, 则返回空
function WuKongFacade:GetElementExtraConfig(id: string): any
	return WuKongFacade.__facade:GetElementExtraConfig(id)
end

--- 查询指定路径容器是否存在
function WuKongFacade:IsPathExist(id: string): any
	return WuKongFacade.__facade:GetElementExtraConfig(id)
end

export type Type = typeof(WuKongFacade.new())

return WuKongFacade
